def _deny_network_access(event: str, _arguments: tuple[Any, ...]) -> None:
    """Enforce the product's offline contract before third-party imports run."""
    if event == "socket.connect":
        raise PermissionError("离线识别运行时禁止建立网络连接。")


sys.addaudithook(_deny_network_access)


class _SystemMemoryStatus(ctypes.Structure):
    _fields_ = [
        ("length", ctypes.c_ulong),
        ("memory_load", ctypes.c_ulong),
        ("total_physical", ctypes.c_ulonglong),
        ("available_physical", ctypes.c_ulonglong),
        ("total_page_file", ctypes.c_ulonglong),
        ("available_page_file", ctypes.c_ulonglong),
        ("total_virtual", ctypes.c_ulonglong),
        ("available_virtual", ctypes.c_ulonglong),
        ("available_extended_virtual", ctypes.c_ulonglong),
    ]


def _available_memory_bytes() -> tuple[int, int] | None:
    if os.name != "nt":
        return None
    status = _SystemMemoryStatus()
    status.length = ctypes.sizeof(_SystemMemoryStatus)
    try:
        succeeded = ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(status))
    except (AttributeError, OSError):
        return None
    if not succeeded:
        return None
    return int(status.available_physical), int(status.available_page_file)


def _require_recognition_memory_headroom() -> None:
    available = _available_memory_bytes()
    if available is None:
        return
    available_physical, available_page_file = available
    if (
        available_physical >= _MINIMUM_AVAILABLE_MEMORY_BYTES
        and available_page_file >= _MINIMUM_AVAILABLE_MEMORY_BYTES
    ):
        return
    raise MemoryError(
        "可用内存不足：识别至少需要保留 4 GB 可用物理内存和分页空间；"
        "请先保存工作并关闭部分占用内存较大的软件后重试"
    )


def _flush_runtime_trace(force: bool = False) -> None:
    global _runtime_trace_buffer, _runtime_trace_last_flush
    if _runtime_trace_file is None or not _runtime_trace_buffer:
        return
    now = time.monotonic()
    if (
        not force
        and len(_runtime_trace_buffer) < 64
        and now - _runtime_trace_last_flush < 0.5
    ):
        return
    try:
        _runtime_trace_file.write("".join(_runtime_trace_buffer))
        _runtime_trace_file.flush()
        _runtime_trace_buffer = []
        _runtime_trace_last_flush = now
    except OSError:
        # Performance tracing must never make recognition fail.
        _runtime_trace_buffer = []


def _write_runtime_trace(
    event: str, *, force_flush: bool = False, **values: Any
) -> None:
    if not _runtime_trace_active:
        return
    payload = {
        "event": event,
        "timestamp": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime()),
        "epoch_seconds": round(time.time(), 3),
        "elapsed_seconds": round(
            max(0.0, time.monotonic() - _runtime_trace_started), 3
        ),
    }
    payload.update(values)
    _runtime_trace_buffer.append(
        json.dumps(payload, ensure_ascii=False, separators=(",", ":")) + "\n"
    )
    _flush_runtime_trace(force_flush)


def _begin_runtime_trace(image_path: Any) -> None:
    global _runtime_trace_active, _runtime_trace_started
    global _runtime_trace_model_totals, _runtime_trace_file
    global _runtime_trace_buffer, _runtime_trace_last_flush
    _runtime_trace_started = time.monotonic()
    _runtime_trace_model_totals = {}
    _runtime_trace_buffer = []
    _runtime_trace_last_flush = _runtime_trace_started
    if _ocr_engine is not None:
        _ocr_engine.reset_execution_profile()
    if _runtime_trace_file is not None:
        try:
            _runtime_trace_file.close()
        except OSError:
            pass
        _runtime_trace_file = None
    try:
        _RUNTIME_TRACE_PATH.parent.mkdir(parents=True, exist_ok=True)
        _runtime_trace_file = _RUNTIME_TRACE_PATH.open(
            "w", encoding="utf-8", buffering=65536
        )
    except OSError:
        _runtime_trace_file = None
    _runtime_trace_active = True
    _write_runtime_trace(
        "request_start",
        force_flush=True,
        image_name=Path(str(image_path)).name,
        process_id=os.getpid(),
    )


def _finish_runtime_trace() -> None:
    global _runtime_trace_active, _runtime_trace_file, _runtime_trace_buffer
    _write_runtime_trace(
        "request_end", force_flush=True, profile=_runtime_trace_summary()
    )
    _runtime_trace_active = False
    if _runtime_trace_file is not None:
        try:
            _runtime_trace_file.close()
        except OSError:
            pass
        _runtime_trace_file = None
    _runtime_trace_buffer = []


def _runtime_trace_summary() -> dict[str, Any]:
    summary = {
        "trace_path": str(_RUNTIME_TRACE_PATH),
        "elapsed_seconds": round(
            max(0.0, time.monotonic() - _runtime_trace_started), 3
        ),
        "models": {
            name: {
                "calls": int(values.get("calls", 0)),
                "images": int(values.get("images", 0)),
                "seconds": round(float(values.get("seconds", 0.0)), 3),
            }
            for name, values in _runtime_trace_model_totals.items()
        },
        "evidence_cache": {
            "hits": _recognition_evidence_hits,
            "misses": _recognition_evidence_misses,
            "entries": len(_recognition_evidence_cache),
        },
        "ordered_batch_evidence_cache": {
            "hits": _ordered_batch_evidence_hits,
            "misses": _ordered_batch_evidence_misses,
            "entries": len(_ordered_batch_evidence_cache),
        },
        "page_evidence_cache": {
            "hits": _page_evidence_hits,
            "misses": _page_evidence_misses,
            "entries": len(_page_evidence_cache),
        },
    }
    if _ocr_engine is not None:
        summary["recognition_scheduler"] = _ocr_engine.execution_profile()
    return summary


def _recognition_batch_size(args: tuple[Any, ...], kwargs: dict[str, Any]) -> int:
    recognition_input = args[0] if args else kwargs.get("input")
    images = getattr(recognition_input, "img", None)
    if images is None:
        return 1
    if hasattr(images, "shape") and hasattr(images, "dtype"):
        return 1
    try:
        return len(images)
    except TypeError:
        return 1


def _recognition_batch_geometry(
    args: tuple[Any, ...], kwargs: dict[str, Any]
) -> dict[str, int | float]:
    recognition_input = args[0] if args else kwargs.get("input")
    images = getattr(recognition_input, "img", None)
    if images is None:
        return {}
    image_list = [images] if hasattr(images, "shape") else list(images)
    shapes = [image.shape[:2] for image in image_list if hasattr(image, "shape")]
    if not shapes:
        return {}
    return {
        "max_width": max(int(width) for _, width in shapes),
        "max_height": max(int(height) for height, _ in shapes),
        "max_aspect": round(
            max(float(width) / max(1.0, float(height)) for height, width in shapes),
            3,
        ),
        "total_pixels": sum(int(height) * int(width) for height, width in shapes),
    }


def _timed_recognition_call(
    model_name: str,
    recognizer: Any,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
) -> Any:
    batch_size = _recognition_batch_size(args, kwargs)
    # A model call can block for minutes on a dense table. Publish the start
    # event immediately so the external monitor shows the real active stage.
    _write_runtime_trace(
        "model_start",
        force_flush=True,
        model=model_name,
        images=batch_size,
        caller=sys._getframe(3).f_code.co_name,
        **_recognition_batch_geometry(args, kwargs),
    )
    started = time.perf_counter()
    status = "ok"
    try:
        return recognizer(*args, **kwargs)
    except Exception:
        status = "error"
        raise
    finally:
        duration = max(0.0, time.perf_counter() - started)
        totals = _runtime_trace_model_totals.setdefault(
            model_name, {"calls": 0, "images": 0, "seconds": 0.0}
        )
        totals["calls"] = int(totals["calls"]) + 1
        totals["images"] = int(totals["images"]) + batch_size
        totals["seconds"] = float(totals["seconds"]) + duration
        _write_runtime_trace(
            "model_end",
            model=model_name,
            images=batch_size,
            duration_seconds=round(duration, 3),
            status=status,
        )


def _begin_recognition_evidence() -> None:
    global _recognition_evidence_active, _recognition_evidence_cache
    global _ordered_batch_evidence_cache
    global _ordered_batch_evidence_hits, _ordered_batch_evidence_misses
    global _page_evidence_cache, _page_evidence_hits, _page_evidence_misses
    global _recognition_evidence_hits, _recognition_evidence_misses
    _recognition_evidence_active = True
    _recognition_evidence_cache = {}
    _ordered_batch_evidence_cache = {}
    _page_evidence_cache = {}
    _recognition_evidence_hits = 0
    _recognition_evidence_misses = 0
    _ordered_batch_evidence_hits = 0
    _ordered_batch_evidence_misses = 0
    _page_evidence_hits = 0
    _page_evidence_misses = 0


def _finish_recognition_evidence() -> None:
    global _recognition_evidence_active, _recognition_evidence_cache
    global _ordered_batch_evidence_cache
    global _page_evidence_cache
    _recognition_evidence_active = False
    # Only text and scores are cached, but release them between requests so a
    # long-running tablet session has a fixed per-image memory lifetime.
    _recognition_evidence_cache = {}
    _ordered_batch_evidence_cache = {}
    _page_evidence_cache = {}


def _image_evidence_key(model_name: str, image: Any) -> tuple[Any, ...] | None:
    if image is None or not hasattr(image, "shape") or not hasattr(image, "dtype"):
        return None
    try:
        contiguous = np.ascontiguousarray(image)
        digest = hashlib.blake2b(
            memoryview(contiguous), digest_size=16
        ).digest()
        return (
            model_name,
            tuple(int(value) for value in contiguous.shape),
            str(contiguous.dtype),
            digest,
        )
    except (TypeError, ValueError, BufferError):
        return None


def _page_output_from_evidence(
    evidence: tuple[Any, Any, Any], evidence_key: tuple[Any, ...]
) -> SimpleNamespace:
    boxes, texts, scores = evidence
    return SimpleNamespace(
        boxes=copy.deepcopy(boxes),
        txts=copy.deepcopy(texts),
        scores=copy.deepcopy(scores),
        imgs=None,
        _evidence_key=evidence_key,
    )


def _cached_page_recognition_call(
    recognizer: Any,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
) -> Any:
    global _page_evidence_hits, _page_evidence_misses
    if not _recognition_evidence_active or len(args) != 1 or kwargs:
        return _timed_recognition_call("page-mobile", recognizer, args, kwargs)
    image = args[0]
    key = _image_evidence_key("page-mobile", image)
    if key is None:
        return _timed_recognition_call("page-mobile", recognizer, args, kwargs)
    cached = _page_evidence_cache.get(key)
    if cached is not None:
        _page_evidence_hits += 1
        return _page_output_from_evidence(cached, key)

    _page_evidence_misses += 1
    output = _timed_recognition_call("page-mobile", recognizer, args, kwargs)
    _release_recognition_images(output)
    setattr(output, "_evidence_key", key)
    if all(hasattr(output, name) for name in ("boxes", "txts", "scores")):
        _page_evidence_cache[key] = (
            copy.deepcopy(output.boxes),
            copy.deepcopy(output.txts),
            copy.deepcopy(output.scores),
        )
    return output


def _cached_text_recognition_call(
    model_name: str,
    recognizer: Any,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
) -> Any:
    global _recognition_evidence_hits, _recognition_evidence_misses
    global _ordered_batch_evidence_hits, _ordered_batch_evidence_misses
    recognition_input = args[0] if args else kwargs.get("input")
    images = getattr(recognition_input, "img", None)
    if (
        not _recognition_evidence_active
        or images is None
        or bool(getattr(recognition_input, "return_word_box", False))
        or len(args) > 1
        or bool(kwargs)
    ):
        return _timed_recognition_call(model_name, recognizer, args, kwargs)
    if hasattr(images, "shape") and hasattr(images, "dtype"):
        image_list = [images]
    else:
        try:
            image_list = list(images)
        except TypeError:
            return _timed_recognition_call(model_name, recognizer, args, kwargs)
    if not image_list:
        return _timed_recognition_call(model_name, recognizer, args, kwargs)

    keys = [_image_evidence_key(model_name, image) for image in image_list]
    if any(key is None for key in keys):
        return _timed_recognition_call(model_name, recognizer, args, kwargs)

    # Mobile and Medium normalize each image against the widest neighbour in
    # their internal batch. Reuse is safe only when the entire ordered batch is
    # byte-for-byte identical; never remove cached members or rebuild the batch.
    if int(getattr(recognizer, "rec_batch_num", 0) or 0) != 1:
        batch_key = ("ordered_batch", model_name, tuple(keys))
        cached_batch = _ordered_batch_evidence_cache.get(batch_key)
        if cached_batch is not None:
            _ordered_batch_evidence_hits += 1
            texts, scores = cached_batch
            return SimpleNamespace(
                txts=list(texts), scores=list(scores), imgs=None
            )
        _ordered_batch_evidence_misses += 1
        output = _timed_recognition_call(model_name, recognizer, args, kwargs)
        _release_recognition_images(output)
        output_texts = [str(text) for text in output.txts]
        output_scores = [float(score) for score in output.scores]
        if (
            len(output_texts) == len(image_list)
            and len(output_scores) == len(image_list)
        ):
            _ordered_batch_evidence_cache[batch_key] = (
                output_texts,
                output_scores,
            )
        return output

    texts = [""] * len(image_list)
    scores = [0.0] * len(image_list)
    missing_positions: list[int] = []
    positions_by_missing_key: dict[tuple[Any, ...], list[int]] = {}
    for position, key in enumerate(keys):
        cached = _recognition_evidence_cache.get(key)
        if cached is None:
            matching_positions = positions_by_missing_key.setdefault(key, [])
            matching_positions.append(position)
            if len(matching_positions) == 1:
                missing_positions.append(position)
                _recognition_evidence_misses += 1
            else:
                # Identical cells can occur repeatedly in one table. They are
                # the same model evidence, so infer the pixels once and fan the
                # exact result back out to every matching position.
                _recognition_evidence_hits += 1
        else:
            texts[position], scores[position] = cached
            _recognition_evidence_hits += 1

    if missing_positions:
        missing_images = [image_list[position] for position in missing_positions]
        try:
            missing_input = type(recognition_input)(img=missing_images)
        except (TypeError, ValueError):
            return _timed_recognition_call(model_name, recognizer, args, kwargs)
        if args:
            missing_args = (missing_input, *args[1:])
            missing_kwargs = kwargs
        else:
            missing_args = ()
            missing_kwargs = dict(kwargs)
            missing_kwargs["input"] = missing_input
        output = _timed_recognition_call(
            model_name, recognizer, missing_args, missing_kwargs
        )
        output_texts = [str(text) for text in output.txts]
        output_scores = [float(score) for score in output.scores]
        _release_recognition_images(output)
        if (
            len(output_texts) != len(missing_positions)
            or len(output_scores) != len(missing_positions)
        ):
            # Preserve the recognizer's original full-batch contract if a
            # backend ever returns an unexpected result length.
            return _timed_recognition_call(
                model_name, recognizer, args, kwargs
            )
        for source_position, text, score in zip(
            missing_positions, output_texts, output_scores
        ):
            key = keys[source_position]
            _recognition_evidence_cache[key] = (text, score)
            for position in positions_by_missing_key[key]:
                texts[position] = text
                scores[position] = score

    return SimpleNamespace(txts=texts, scores=scores, imgs=None)


class _RecognitionBudget:
    """Monotonic per-image budget; zero seconds means no deadline."""

    def __init__(self, seconds: float, clock: Any = None):
        requested_seconds = float(seconds)
        self.unlimited = requested_seconds <= 0.0
        self.seconds = 0.0 if self.unlimited else max(1.0, requested_seconds)
        self._clock = clock or time.monotonic
        self._started = self._clock()
        self._deadline = math.inf if self.unlimited else self._started + self.seconds
        self.limited = False

    def elapsed(self) -> float:
        return max(0.0, self._clock() - self._started)

    def remaining(self) -> float:
        if self.unlimited:
            return math.inf
        return max(0.0, self._deadline - self._clock())

    def allow(self, minimum_remaining: float = 0.0) -> bool:
        if self.unlimited:
            return True
        allowed = self.remaining() >= max(0.0, float(minimum_remaining))
        if not allowed:
            self.limited = True
        return allowed

    def reached(self) -> bool:
        if self.unlimited:
            return False
        return self.remaining() <= 0.0

